// DEV_RIO_301 Performance & Revenue Decision — dry-run
// 実運用では metrics.csv / attribution / YU HOLDINGS AI MCP から実測を投入。
// 欠損は unknown、推定と実測を分離（design/SECURITY_POLICY.md）。
const i = $input.first().json;
return [{ json: {
  experiment_id: i.experiment_id ?? 'exp-001',
  impressions: i.impressions ?? 0,
  clicks: i.clicks ?? 0,
  note_visits: i.note_visits ?? 0,
  brain_visits: i.brain_visits ?? 0,
  purchases: i.purchases ?? 0,
  confirmed_revenue: i.confirmed_revenue ?? 0,
  api_cost: i.api_cost ?? 0,
  browser_cost: i.browser_cost ?? 0,
  owner_hours: i.owner_hours ?? 0,
  source: i.source ?? 'actual'
} }];

// KPI・費用集計。最上位KPI=承認粗利益÷オーナー稼働（design/REVENUE_LOOP_MVP.md）。
const o = $input.first().json;
const total_cost = (o.api_cost || 0) + (o.browser_cost || 0);
const gross_profit = (o.confirmed_revenue || 0) - total_cost;
const kpi = o.owner_hours > 0 ? +(gross_profit / o.owner_hours).toFixed(1) : null; // 円/時
const enough_data = (o.impressions >= 1000) || (o.clicks >= 50);
return [{ json: { ...o, total_cost, gross_profit, kpi_profit_per_hour: kpi, enough_data } }];

// 判定: SCALE / ITERATE / HOLD / STOP（少データは HOLD。因果断定しない）。
const o = $input.first().json;
let decision, rationale;
if (!o.enough_data) {
  decision = 'HOLD';
  rationale = '最小データ未達（≥1000表示 or ≥50クリック）。継続観察。';
} else if (o.purchases > 0 && (o.kpi_profit_per_hour ?? 0) > 0) {
  decision = 'SCALE';
  rationale = '購入発生＋粗利/稼働が正。再現確認のうえ増産/多媒体。';
} else if (o.brain_visits > 0 && o.purchases === 0) {
  decision = 'ITERATE';
  rationale = '遷移はあるが未購入。単一レバー(価格/CTA/オファー)を1つ変更。';
} else {
  decision = 'STOP';
  rationale = '十分データで明確な負。archive候補（削除はしない・人間承認）。';
}
return [{ json: { ...o, decision, rationale, owner_yes_no: 'PENDING',
  note: 'dry-run。data/decisions.csv 追記候補。実行(拡大/停止)は人間Yes後。' } }];
